// Resolve the PS3 GXEMU LV1 VUART wrapper callers and audit candidate port 10 routes.
// @category PS3.PS2Emulation
// For Ghidra 12.1.x / PowerPC:BE:64:A2ALT (big endian).
// Verified wrapper symbols are renamed if and only if existing names are autogenerated.
// Does not change bytes, signatures, storage, data types, or unexplained function boundaries.

import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSpace;
import ghidra.program.model.lang.Register;
import ghidra.program.model.listing.Function;
import ghidra.program.model.listing.Instruction;
import ghidra.program.model.mem.MemoryBlock;
import ghidra.program.model.pcode.PcodeOp;
import ghidra.program.model.pcode.Varnode;
import ghidra.program.model.symbol.Reference;
import ghidra.program.model.symbol.ReferenceIterator;
import ghidra.program.model.symbol.SourceType;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

public class TracePs3GxemuVuartCallers_20261016_v2 extends GhidraScript {
    private static final boolean APPLY_VERIFIED_RENAMES = true;
    private static final int MAX_BACK = 24;
    private static final int MAX_REFS_PRINT = 120;
    private static final int MAX_OPD_PRINT = 32;

    private static class Target {
        final long entry;
        final String name;
        final long[] scSites;
        final int[] scIds;

        Target(long e, String n, long[] sites, int[] ids) {
            entry = e; name = n; scSites = sites; scIds = ids;
        }
    }

    private static final Target[] TARGETS = {
        new Target(0x000494a4L, "Lv1WriteVirtualUart",
            new long[] {0x000494e0L}, new int[] {163}),
        new Target(0x00049544L, "Lv1ReadVirtualUart",
            new long[] {0x00049564L}, new int[] {162}),
        new Target(0x000495b8L, "Lv1VirtualUartParameterDispatch",
            new long[] {0x000495e0L, 0x000495f8L, 0x00049628L},
            new int[] {164, 165, 164}),
        new Target(0x00049664L, "Lv1ConfigureVirtualUartIrq",
            new long[] {0x00049680L}, new int[] {166})
    };

    private Address toAddress(long offset) {
        return currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(offset);
    }

    private boolean writesRegister(Instruction ins, Register reg) {
        for (PcodeOp op : ins.getPcode()) {
            Varnode out = op.getOutput();
            if (out != null && out.isRegister() && out.getAddress().equals(reg.getAddress()))
                return true;
        }
        return false;
    }

    // Resolve only contiguous, straight-line li/lis [+ ori] for an argument register.
    // Treat results as local candidates because other incoming CFG edges can exist.
    private Long localImmediate(Instruction site, Register reg, int number) throws Exception {
        Instruction next = site;
        Integer low = null;
        for (int i = 0; i < MAX_BACK; ++i) {
            monitor.checkCancelled();
            Instruction prev = currentProgram.getListing().getInstructionBefore(next.getAddress());
            if (prev == null || prev.getLength() != 4 ||
                prev.getFallThrough() == null ||
                !prev.getFallThrough().equals(next.getAddress()) ||
                prev.getFlowType().isJump() || prev.getFlowType().isCall() ||
                prev.getFlowType().isTerminal())
                return null;

            int w = currentProgram.getMemory().getInt(prev.getAddress());
            int op = w >>> 26;
            if (op == 17)
                return null;
            int rt = (w >>> 21) & 31;
            int ra = (w >>> 16) & 31;
            int imm = w & 0xffff;
            if (op == 24 && rt == number && ra == number) {
                if (low != null)
                    return null;
                low = imm;
                next = prev;
                continue;
            }
            if ((op == 14 || op == 15) && rt == number && ra == 0) {
                long value = op == 14 ? (long)(short)imm : ((long)(short)imm << 16);
                if (low != null)
                    value |= (long)low;
                return value;
            }
            if (writesRegister(prev, reg))
                return null;
            next = prev;
        }
        return null;
    }

    private boolean verify(Target target) throws Exception {
        Function f = currentProgram.getFunctionManager().getFunctionAt(toAddress(target.entry));
        if (f == null) {
            println(String.format("VERIFY_FAIL 0x%08X expected function entry missing", target.entry));
            return false;
        }
        Register r11 = currentProgram.getRegister("r11");
        if (r11 == null)
            return false;
        for (int i = 0; i < target.scSites.length; ++i) {
            Address scAddr = toAddress(target.scSites[i]);
            Instruction sc = currentProgram.getListing().getInstructionAt(scAddr);
            if (sc == null || sc.getLength() != 4 ||
                currentProgram.getMemory().getInt(scAddr) != 0x44000022 ||
                currentProgram.getFunctionManager().getFunctionContaining(scAddr) == null ||
                !currentProgram.getFunctionManager().getFunctionContaining(scAddr).getEntryPoint().equals(f.getEntryPoint())) {
                println(String.format("VERIFY_FAIL 0x%08X sc-site 0x%08X does not belong to wrapper / lacks sc 1",
                    target.entry, target.scSites[i]));
                return false;
            }
            Long id = localImmediate(sc, r11, 11);
            if (id == null || id.longValue() != target.scIds[i]) {
                println(String.format("VERIFY_FAIL 0x%08X sc-site 0x%08X selector expected=%d actual=%s",
                    target.entry, target.scSites[i], target.scIds[i], String.valueOf(id)));
                return false;
            }
        }
        println(String.format("VERIFY_PASS 0x%08X %s hypercalls=%d", target.entry, target.name, target.scSites.length));
        if (APPLY_VERIFIED_RENAMES && f.getName().startsWith("FUN_")) {
            String prior = f.getName();
            f.setName(target.name, SourceType.USER_DEFINED);
            println("RENAME " + prior + " -> " + target.name + " @ " + f.getEntryPoint());
        } else {
            println("PRESERVE_NAME " + f.getName() + " @ " + f.getEntryPoint());
        }
        return true;
    }

    private int printReferences(Address destination, String kind) throws Exception {
        ReferenceIterator it = currentProgram.getReferenceManager().getReferencesTo(destination);
        int total = 0;
        Register r3 = currentProgram.getRegister("r3");
        while (it.hasNext()) {
            monitor.checkCancelled();
            Reference ref = it.next();
            total++;
            if (total > MAX_REFS_PRINT)
                continue;
            Address from = ref.getFromAddress();
            Function caller = currentProgram.getFunctionManager().getFunctionContaining(from);
            Instruction ins = currentProgram.getListing().getInstructionAt(from);
            Long port = (ins == null || r3 == null || !ref.getReferenceType().isCall()) ?
                null : localImmediate(ins, r3, 3);
            String owner = caller == null ? "<no-function>" :
                caller.getName() + "@" + caller.getEntryPoint();
            println(String.format(
                "REF kind=%s target=%s from=%s type=%s owner=%s op=%s local_r3=%s%s",
                kind, destination, from, ref.getReferenceType(), owner,
                ins == null ? "<not-an-instruction>" : ins.toString(),
                port == null ? "unresolved" : String.format("0x%X", port),
                port != null && port == 10L ? " PORT10_LINEAR_CANDIDATE" : ""));
        }
        if (total > MAX_REFS_PRINT)
            println("REF_TRUNCATED target=" + destination + " omitted=" + (total - MAX_REFS_PRINT));
        return total;
    }

    // A normal PowerPC64 OPD descriptor has 8-byte entry address + 8-byte TOC.
    // Log candidates only, never declare types or treat them as verified functions.
    private Map<Long,List<Address>> findPossibleOpdDescriptors() throws Exception {
        Map<Long,List<Address>> found = new HashMap<Long,List<Address>>();
        Set<Long> targets = new HashSet<Long>();
        for (Target t : TARGETS)
            targets.add(t.entry);

        int scanned = 0;
        for (MemoryBlock b : currentProgram.getMemory().getBlocks()) {
            monitor.checkCancelled();
            if (!b.isInitialized() || !b.isRead() || b.isExecute() ||
                !b.getStart().getAddressSpace().isMemorySpace())
                continue;
            long first = (b.getStart().getOffset() + 7L) & ~7L;
            long last = b.getEnd().getOffset();
            AddressSpace space = b.getStart().getAddressSpace();
            for (long off = first; off + 15 <= last; off += 8) {
                if ((scanned++ & 8191) == 0)
                    monitor.checkCancelled();
                Address addr = space.getAddress(off);
                long entryValue;
                long tocValue;
                try {
                    entryValue = currentProgram.getMemory().getLong(addr);
                    tocValue = currentProgram.getMemory().getLong(addr.add(8));
                } catch (Exception e) {
                    continue;
                }
                if (!targets.contains(entryValue))
                    continue;
                boolean mappedToc = false;
                try {
                    mappedToc = currentProgram.getMemory().contains(space.getAddress(tocValue));
                } catch (Exception ignored) {
                    // A non-address-space TOC is evidence against an OPD descriptor.
                }
                println(String.format("OPD_CANDIDATE address=%s entry=0x%X toc=0x%X mappedToc=%b",
                    addr, entryValue, tocValue, mappedToc));
                List<Address> list = found.get(entryValue);
                if (list == null) {
                    list = new ArrayList<Address>();
                    found.put(entryValue, list);
                }
                list.add(addr);
            }
        }
        println("OPD_SCAN_CELLS=" + scanned);
        return found;
    }

    private void dumpContext(long offset, int before, int after) throws Exception {
        Instruction at = currentProgram.getListing().getInstructionAt(toAddress(offset));
        if (at == null) {
            println(String.format("CONTEXT 0x%08X no instruction", offset));
            return;
        }
        ArrayList<Instruction> context = new ArrayList<Instruction>();
        Instruction p = at;
        for (int i = 0; i < before && p != null; ++i) {
            p = currentProgram.getListing().getInstructionBefore(p.getAddress());
            if (p != null)
                context.add(0, p);
        }
        context.add(at);
        p = at;
        for (int i = 0; i < after && p != null; ++i) {
            p = currentProgram.getListing().getInstructionAfter(p.getAddress());
            if (p != null)
                context.add(p);
        }
        println(String.format("CONTEXT_START 0x%08X", offset));
        for (Instruction ins : context)
            println("  " + ins.getAddress() + " " + ins.toString());
        println("CONTEXT_END");
    }

    @Override
    public void run() throws Exception {
        if (currentProgram == null ||
            !"PowerPC:BE:64:A2ALT".equals(currentProgram.getLanguageID().toString()) ||
            !currentProgram.getName().contains("ps2_gxemu")) {
            printerr("REFUSE: expected 64-bit PowerPC:BE:64:A2ALT ps2_gxemu database");
            return;
        }

        println("GXEMU_VUART_CALLERS APPLY_VERIFIED_RENAMES=" + APPLY_VERIFIED_RENAMES);
        int valid = 0;
        for (Target t : TARGETS)
            if (verify(t)) valid++;
        if (valid != TARGETS.length) {
            printerr("ABORT: some expected wrappers did not verify. No caller assertions.");
            return;
        }

        int incoming = 0;
        for (Target t : TARGETS)
            incoming += printReferences(toAddress(t.entry), "CODE_ENTRY");

        Map<Long,List<Address>> descriptors = findPossibleOpdDescriptors();
        int descriptorRefs = 0;
        for (Target t : TARGETS) {
            List<Address> hits = descriptors.get(t.entry);
            if (hits == null)
                continue;
            int shown = 0;
            for (Address addr : hits) {
                if (++shown > MAX_OPD_PRINT)
                    break;
                descriptorRefs += printReferences(addr, "OPD_CANDIDATE");
            }
        }

        // This read call currently has no containing function. Observe first; do not promote.
        Address orphan = toAddress(0x00049748L);
        println("ORPHAN_READ_0x49748 owner=" +
            currentProgram.getFunctionManager().getFunctionContaining(orphan));
        dumpContext(0x00049748L, 15, 12);
        println("SUMMARY validWrappers=" + valid + " directIncomingRefs=" + incoming +
            " descriptorIncomingRefs=" + descriptorRefs);
        println("NOTE: OPD, port 10, and calling-flow observations are leads, not proof of MagicGate semantics.");
        println("DONE: no arbitrary data types, signatures, function promotions, or executable byte changes.");
    }
}
